CREATE TABLE `contacts` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT COMMENT 'Identificador ├║nico del contacto',
  `uuid` char(36) NOT NULL COMMENT 'UUID universal ├║nico del contacto',
  `company_uuid` char(36) NOT NULL COMMENT 'UUID de la empresa a la que pertenece el contacto',
  `first_name` varchar(100) DEFAULT NULL COMMENT 'Nombres del contacto',
  `last_name` varchar(100) DEFAULT NULL COMMENT 'Apellidos del contacto',
  `representative_type` enum('COMERCIAL','REPRESENTANTE_LEGAL','TECNICO','CARTERA','COMPRAS','CONTACTO_FACTURACION','CUMPLIMIENTO','FINANCIERO','HSE','JURIDICO','REPRESENTANTE_LEGAL_SUPLENTE') NOT NULL COMMENT 'Cargo o funci├│n del contacto en la organizaci├│n',
  `country` varchar(100) DEFAULT NULL COMMENT 'Pa├¡s de residencia o ubicaci├│n',
  `municipality_uuid` char(36) DEFAULT NULL COMMENT 'UUID del municipio de ubicaci├│n',
  `email` varchar(150) DEFAULT NULL COMMENT 'Correo electr├│nico de contacto',
  `phone_number` varchar(50) DEFAULT NULL COMMENT 'N├║mero de tel├®fono de contacto',
  `remarks` text DEFAULT NULL COMMENT 'Observaciones o notas adicionales sobre el contacto',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `contacts_uuid_unique` (`uuid`),
  KEY `contacts_company_uuid_foreign` (`company_uuid`),
  KEY `contacts_municipality_uuid_foreign` (`municipality_uuid`),
  CONSTRAINT `contacts_company_uuid_foreign` FOREIGN KEY (`company_uuid`) REFERENCES `companies` (`uuid`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `contacts_municipality_uuid_foreign` FOREIGN KEY (`municipality_uuid`) REFERENCES `cities` (`uuid`) ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
