--
-- Table structure for table `notifications`
--

DROP TABLE IF EXISTS `notifications`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `notifications` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT COMMENT 'Identificador interno autoincremental',
  `uuid` char(36) NOT NULL COMMENT 'UUID v4 ├║nico de la notificaci├│n/alerta',
  `company_uuid` char(36) NOT NULL COMMENT 'UUID de la empresa asociada (tenant)',
  `type` varchar(50) NOT NULL COMMENT 'Categor├¡a de la alerta (ej: SOAT, RTM, LICENCIA, etc.)',
  `title` varchar(150) NOT NULL COMMENT 'T├¡tulo descriptivo de la notificaci├│n',
  `message` text NOT NULL COMMENT 'Cuerpo o mensaje detallado de la alerta',
  `status` enum('PENDIENTE','LEIDA') NOT NULL DEFAULT 'PENDIENTE' COMMENT 'Estado de lectura de la alerta',
  `priority` enum('PRIORITARIA','NORMAL') NOT NULL DEFAULT 'NORMAL' COMMENT 'Prioridad de la alerta: propia (veh├¡culo de la empresa) o normal',
  `entity_uuid` char(36) DEFAULT NULL COMMENT 'UUID de la entidad origen que deton├│ la alerta',
  `entity_type` varchar(100) DEFAULT NULL COMMENT 'Modelo/Clase Eloquent de la entidad origen',
  `days_left` int(11) DEFAULT NULL COMMENT 'D├¡as restantes para el vencimiento al momento de generar la alerta',
  `expiry_date` date DEFAULT NULL COMMENT 'Fecha de vencimiento/vencida',
  `extra_data` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'Detalles t├®cnicos o metadatos de la alerta' CHECK (json_valid(`extra_data`)),
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `notifications_uuid_unique` (`uuid`),
  KEY `notifications_company_uuid_index` (`company_uuid`),
  KEY `notifications_entity_uuid_index` (`entity_uuid`),
  KEY `notifications_company_status_priority_idx` (`company_uuid`,`status`,`priority`,`created_at`)
) ENGINE=InnoDB AUTO_INCREMENT=621 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

