DROP TABLE IF EXISTS `signatures`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `signatures` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT COMMENT 'Identificador ├║nico de la firma',
  `uuid` char(36) NOT NULL COMMENT 'UUID ├║nico universal de la firma',
  `entity_type` varchar(255) NOT NULL COMMENT 'Tipo de entidad',
  `entity_id` bigint(20) unsigned NOT NULL COMMENT 'ID de la entidad',
  `signer_role` varchar(30) DEFAULT NULL COMMENT 'conductor|funcionario|coordinador; NULL = rol no determinable (legado)',
  `scope` varchar(30) DEFAULT NULL COMMENT 'planilla|recorrido',
  `status` varchar(20) NOT NULL DEFAULT 'vigente' COMMENT 'vigente|reemplazada|revocada',
  `signed_at` timestamp NULL DEFAULT NULL COMMENT 'Momento real de la firma',
  `signer_uuid` char(36) DEFAULT NULL COMMENT 'UUID del firmante; NULL en subcontratados con datos en texto libre',
  `company_uuid` char(36) NOT NULL COMMENT 'UUID ├║nico universal de la empresa',
  `ip_address` varchar(45) DEFAULT NULL COMMENT 'Direcci├│n IP de la firma',
  `latitude` varchar(255) DEFAULT NULL COMMENT 'Latitud de la firma',
  `longitude` varchar(255) DEFAULT NULL COMMENT 'Longitud de la firma',
  `path` varchar(255) NOT NULL COMMENT 'Ruta del archivo de la firma',
  `disk` varchar(50) NOT NULL DEFAULT 'public' COMMENT 'Disco del archivo de la firma',
  `mime_type` varchar(50) NOT NULL DEFAULT 'image/png' COMMENT 'Tipo de archivo',
  `size_bytes` bigint(20) unsigned DEFAULT NULL COMMENT 'Tama├▒o del archivo',
  `speed` varchar(50) DEFAULT NULL COMMENT 'Velocidad de la firma',
  `state` enum('DETENIDO','EN MOVIMIENTO') NOT NULL DEFAULT 'DETENIDO' COMMENT 'Estado de la firma',
  `deleted_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `signatures_uuid_unique` (`uuid`),
  KEY `idx_signatures_entity` (`entity_type`,`entity_id`),
  KEY `signatures_company_uuid_foreign` (`company_uuid`),
  KEY `idx_signatures_entity_role` (`entity_type`,`entity_id`,`signer_role`,`status`),
  CONSTRAINT `signatures_company_uuid_foreign` FOREIGN KEY (`company_uuid`) REFERENCES `companies` (`uuid`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
