CREATE TABLE `users` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT COMMENT 'Identificador ├║nico autoincremental',
  `name` varchar(255) NOT NULL COMMENT 'Nombre del usuario',
  `uuid` char(36) NOT NULL COMMENT 'Identificador ├║nico universal',
  `email` varchar(255) NOT NULL COMMENT 'Correo electr├│nico ├║nico',
  `user_name` varchar(255) DEFAULT NULL COMMENT 'Nombre de usuario, puede ser ├║nico si aplica',
  `email_verified_at` timestamp NULL DEFAULT NULL COMMENT 'Fecha de verificaci├│n de correo',
  `password` varchar(255) NOT NULL COMMENT 'Contrase├▒a',
  `verification_code` varchar(255) DEFAULT NULL COMMENT 'C├│digo de verificaci├│n',
  `verification_code_expires_at` timestamp NULL DEFAULT NULL COMMENT 'Expiraci├│n del c├│digo de verificaci├│n',
  `last_login_at` timestamp NULL DEFAULT NULL COMMENT '├Ültimo inicio de sesi├│n',
  `failed_login_attempts` tinyint(3) unsigned NOT NULL DEFAULT 0 COMMENT 'Intentos fallidos de inicio de sesi├│n',
  `locked_until` timestamp NULL DEFAULT NULL COMMENT 'Fecha hasta la que el usuario est├í bloqueado',
  `google_id` varchar(255) DEFAULT NULL COMMENT 'Identificador ├║nico de Google',
  `google_email` varchar(255) DEFAULT NULL COMMENT 'Correo electr├│nico de Google',
  `google_drive_refresh_token` varchar(255) DEFAULT NULL COMMENT 'Token de actualizaci├│n de Google Drive',
  `status` tinyint(4) NOT NULL DEFAULT 1 COMMENT 'Estado del usuario',
  `remember_token` varchar(100) DEFAULT NULL COMMENT 'Token para recordar sesi├│n',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `users_uuid_unique` (`uuid`),
  UNIQUE KEY `users_email_unique` (`email`)
) ENGINE=InnoDB AUTO_INCREMENT=47 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
